# MALFORMED: returns business data directly with no statusCode/body wrapper.
# The function itself runs successfully and logs show no error at all --
# but API Gateway can't turn this into an HTTP response, so the client
# receives a 502 Internal Server Error.
def handler_malformed(event, context):
    return {"orderId": "42", "status": "shipped"}

# CORRECT: wraps the same business data in the shape API Gateway requires.
def handler_correct(event, context):
    import json
    return {
        "statusCode": 200,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps({"orderId": "42", "status": "shipped"})
    }

import json

def handler(event, context):
    method = event["requestContext"]["http"]["method"]
    order_id = event.get("pathParameters", {}).get("orderId")
    query = event.get("queryStringParameters") or {}
    expand_items = query.get("expand") == "items"

    if method != "GET" or not order_id:
        return {"statusCode": 400, "body": json.dumps({"error": "orderId path parameter required"})}

    order = {"orderId": order_id, "status": "shipped"}
    if expand_items:
        order["items"] = [{"sku": "WIDGET-1", "qty": 2}]

    return {
        "statusCode": 200,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(order)
    }

