# shared business logic -- knows nothing about API Gateway or SQS
def place_order_with_tax(order_id: str, amount: float) -> None:
    tax = amount * 0.0825
    place_order(order_id, amount, tax)

# function A: thin adapter for the API Gateway event shape
def api_handler(event, context):
    order_id = event["pathParameters"]["orderId"]
    amount = json.loads(event["body"])["amount"]
    place_order_with_tax(order_id, amount)
    return {"statusCode": 200, "body": json.dumps({"orderId": order_id})}

# function B: thin adapter for the SQS event shape
def sqs_handler(event, context):
    for record in event["Records"]:
        body = json.loads(record["body"])
        place_order_with_tax(body["orderId"], body["amount"])
